    m15 = { headingMain: "\u03A3\u03C5\u03BD\u03AD\u03B2\u03B7 \u03BA\u03AC\u03C0\u03BF\u03B9\u03BF \u03C3\u03C6\u03AC\u03BB\u03BC\u03B1. \u03A0\u03C1\u03BF\u03C3\u03C0\u03AC\u03B8\u03B7\u03C3\u03B5 <button>\u03C6\u03CC\u03C1\u03C4\u03C9\u03C3\u03B5 \u03BE\u03B1\u03BD\u03AC \u03C4\u03B7\u03BD \u03C3\u03B5\u03BB\u03AF\u03B4\u03B1.</button>", clearCanvasMessage: "\u0395\u03AC\u03BD \u03C4\u03BF \u03C0\u03B1\u03C1\u03B1\u03C0\u03AC\u03BD\u03C9 \u03B4\u03B5\u03BD \u03B4\u03BF\u03C5\u03BB\u03AD\u03C8\u03B5\u03B9, \u03C0\u03C1\u03BF\u03C3\u03C0\u03AC\u03B8\u03B7\u03C3\u03B5 <button>\u03BA\u03B1\u03B8\u03B1\u03C1\u03AF\u03C3\u03B5\u03C4\u03B5 \u03C4\u03BF\u03BD \u03BA\u03B1\u03BD\u03B2\u03AC.</button>", clearCanvasCaveat: " \u0391\u03C5\u03C4\u03CC \u03B8\u03B1 \u03C0\u03C1\u03BF\u03BA\u03B1\u03BB\u03AD\u03C3\u03B5\u03B9 \u03B1\u03C0\u03CE\u03BB\u03B5\u03B9\u03B1 \u03C4\u03B7\u03C2 \u03B4\u03BF\u03C5\u03BB\u03B5\u03B9\u03AC\u03C2 \u03C3\u03BF\u03C5 ", trackedToSentry: "\u03A4\u03BF \u03C3\u03C6\u03AC\u03BB\u03BC\u03B1 \u03BC\u03B5 \u03B1\u03BD\u03B1\u03B3\u03BD\u03C9\u03C1\u03B9\u03C3\u03C4\u03B9\u03BA\u03CC {{eventId}} \u03C0\u03B1\u03C1\u03B1\u03BA\u03BF\u03BB\u03BF\u03C5\u03B8\u03AE\u03B8\u03B7\u03BA\u03B5 \u03C3\u03C4\u03BF \u03C3\u03CD\u03C3\u03C4\u03B7\u03BC\u03AC \u03BC\u03B1\u03C2.", openIssueMessage: "\u0389\u03BC\u03B1\u03C3\u03C4\u03B1\u03BD \u03C0\u03BF\u03BB\u03CD \u03C0\u03C1\u03BF\u03C3\u03B5\u03BA\u03C4\u03B9\u03BA\u03BF\u03AF \u03B3\u03B9\u03B1 \u03BD\u03B1 \u03BC\u03B7\u03BD \u03C3\u03C5\u03BC\u03C0\u03B5\u03C1\u03B9\u03BB\u03AC\u03B2\u03BF\u03C5\u03BC\u03B5 \u03C4\u03B9\u03C2 \u03C0\u03BB\u03B7\u03C1\u03BF\u03C6\u03BF\u03C1\u03AF\u03B5\u03C2 \u03C4\u03B7\u03C2 \u03C3\u03BA\u03B7\u03BD\u03AE\u03C2 \u03C3\u03BF\u03C5 \u03C3\u03C4\u03BF \u03C3\u03C6\u03AC\u03BB\u03BC\u03B1. \u0391\u03BD \u03B7 \u03C3\u03BA\u03B7\u03BD\u03AE \u03C3\u03BF\u03C5 \u03B4\u03B5\u03BD \u03B5\u03AF\u03BD\u03B1\u03B9 \u03B9\u03B4\u03B9\u03C9\u03C4\u03B9\u03BA\u03AE, \u03C0\u03B1\u03C1\u03B1\u03BA\u03B1\u03BB\u03CE \u03C3\u03BA\u03AD\u03C8\u03BF\u03C5 \u03BD\u03B1 \u03B1\u03BA\u03BF\u03BB\u03BF\u03C5\u03B8\u03AE\u03C3\u03B5\u03B9\u03C2 \u03C4\u03BF \u03B4\u03B9\u03BA\u03CC \u03BC\u03B1\u03C2 <button>\u03B1\u03BD\u03B9\u03C7\u03BD\u03B5\u03C5\u03C4\u03AE\u03C2 \u03C3\u03C6\u03B1\u03BB\u03BC\u03AC\u03C4\u03C9\u03BD.</button> \u03A0\u03B1\u03C1\u03B1\u03BA\u03B1\u03BB\u03CE \u03BD\u03B1 \u03C3\u03C5\u03BC\u03C0\u03B5\u03C1\u03B9\u03BB\u03AC\u03B2\u03B5\u03C4\u03B5 \u03C4\u03B9\u03C2 \u03C0\u03B1\u03C1\u03B1\u03BA\u03AC\u03C4\u03C9 \u03C0\u03BB\u03B7\u03C1\u03BF\u03C6\u03BF\u03C1\u03AF\u03B5\u03C2, \u03B1\u03BD\u03C4\u03B9\u03B3\u03C1\u03AC\u03C6\u03BF\u03BD\u03C4\u03B1\u03C2 \u03BA\u03B1\u03B9 \u03B5\u03C0\u03B9\u03BA\u03BF\u03BB\u03BB\u03CE\u03BD\u03C4\u03B1\u03C2 \u03C4\u03BF \u03B6\u03AE\u03C4\u03B7\u03BC\u03B1 \u03C3\u03C4\u03BF GitHub.", sceneContent: "\u03A0\u03B5\u03C1\u03B9\u03B5\u03C7\u03CC\u03BC\u03B5\u03BD\u03BF \u03C3\u03BA\u03B7\u03BD\u03AE\u03C2:" };
    p15 = { desc_intro: "\u039C\u03C0\u03BF\u03C1\u03B5\u03AF\u03C2 \u03BD\u03B1 \u03C0\u03C1\u03BF\u03C3\u03BA\u03B1\u03BB\u03AD\u03C3\u03B5\u03B9\u03C2 \u03AC\u03BB\u03BB\u03BF\u03C5\u03C2 \u03BD\u03B1 \u03B4\u03BF\u03C5\u03BB\u03AD\u03C8\u03BF\u03C5\u03BD \u03BC\u03B1\u03B6\u03AF \u03C3\u03BF\u03C5.", desc_privacy: "\u039C\u03B7\u03BD \u03B1\u03BD\u03B7\u03C3\u03C5\u03C7\u03B5\u03AF\u03C2, \u03B7 \u03C3\u03C5\u03BD\u03B5\u03B4\u03C1\u03AF\u03B1 \u03C7\u03C1\u03B7\u03C3\u03B9\u03BC\u03BF\u03C0\u03BF\u03B9\u03B5\u03AF \u03BA\u03C1\u03C5\u03C0\u03C4\u03BF\u03B3\u03C1\u03AC\u03C6\u03B7\u03C3\u03B7 \u03B1\u03C0\u03CC \u03C3\u03B7\u03BC\u03B5\u03AF\u03BF \u03C3\u03B5 \u03C3\u03B7\u03BC\u03B5\u03AF\u03BF, \u03AC\u03C1\u03B1 \u03BF\u03C4\u03B9\u03B4\u03AE\u03C0\u03BF\u03C4\u03B5 \u03BA\u03AC\u03BD\u03B5\u03B9\u03C2 \u03B8\u03B1 \u03C0\u03B1\u03C1\u03B1\u03BC\u03B5\u03AF\u03BD\u03B5\u03B9 \u03B1\u03BD\u03BF\u03B9\u03C7\u03C4\u03CC \u03BC\u03CC\u03BD\u03BF \u03C3\u03B5 \u03B5\u03C3\u03AD\u03BD\u03B1. \u039F\u03CD\u03C4\u03B5 \u03BF\u03B9 \u03BC\u03B7\u03C7\u03B1\u03BD\u03AD\u03C2 \u03BC\u03B1\u03C2 \u03BC\u03C0\u03BF\u03C1\u03BF\u03CD\u03BD \u03BD\u03B1 \u03B4\u03BF\u03C5\u03BD \u03C4\u03B9 \u03BA\u03AC\u03BD\u03B5\u03B9\u03C2.", button_startSession: "\u0388\u03BD\u03B1\u03C1\u03BE\u03B7 \u03A3\u03C5\u03BD\u03B5\u03B4\u03C1\u03AF\u03B1\u03C2", button_stopSession: "\u03A4\u03B5\u03C1\u03BC\u03B1\u03C4\u03B9\u03C3\u03BC\u03CC\u03C2 \u03A3\u03C5\u03BD\u03B5\u03B4\u03C1\u03AF\u03B1\u03C2", desc_inProgressIntro: "\u0397 \u03B6\u03C9\u03BD\u03C4\u03B1\u03BD\u03AE \u03C3\u03C5\u03BD\u03B5\u03C1\u03B3\u03B1\u03C3\u03AF\u03B1 \u03BC\u03B5 \u03AC\u03BB\u03BB\u03BF\u03C5\u03C2 \u03B5\u03AF\u03BD\u03B1\u03B9 \u03C3\u03B5 \u03B5\u03BD\u03B5\u03C1\u03B3\u03AE.", desc_shareLink: "\u039C\u03BF\u03B9\u03C1\u03B1\u03C3\u03C4\u03B5\u03AF\u03C4\u03B5 \u03C4\u03BF\u03BD \u03C3\u03CD\u03BD\u03B4\u03B5\u03C3\u03BC\u03BF \u03BC\u03B5 \u03CC\u03C0\u03BF\u03B9\u03BF\u03BD \u03B8\u03AD\u03BB\u03B5\u03C4\u03B5 \u03BD\u03B1 \u03B4\u03BF\u03C5\u03BB\u03AD\u03C8\u03B5\u03C4\u03B5 \u03BC\u03B1\u03B6\u03AF:", desc_exitSession: "\u0397 \u03B4\u03B9\u03B1\u03BA\u03BF\u03C0\u03AE \u03B8\u03B1 \u03C3\u03B1\u03C2 \u03B1\u03C0\u03BF\u03C3\u03C5\u03BD\u03B4\u03AD\u03C3\u03B5\u03B9 \u03B1\u03C0\u03CC \u03C4\u03BF \u03B4\u03C9\u03BC\u03AC\u03C4\u03B9\u03BF, \u03B1\u03BB\u03BB\u03AC \u03B8\u03B1 \u03BC\u03C0\u03BF\u03C1\u03B5\u03AF\u03C4\u03B5 \u03BD\u03B1 \u03C3\u03C5\u03BD\u03B5\u03C7\u03AF\u03C3\u03B5\u03C4\u03B5 \u03BD\u03B1 \u03B4\u03BF\u03C5\u03BB\u03B5\u03CD\u03B5\u03C4\u03B5 \u03C3\u03C4\u03BF\u03BD \u03C0\u03AF\u03BD\u03B1\u03BA\u03B1, \u03C4\u03BF\u03C0\u03B9\u03BA\u03AC. \u03A3\u03B7\u03BC\u03B5\u03B9\u03CE\u03C3\u03B1\u03C4\u03B5 \u03CC\u03C4\u03B9 \u03B1\u03C5\u03C4\u03CC \u03B4\u03B5\u03BD \u03B8\u03B1 \u03B5\u03C0\u03B7\u03C1\u03B5\u03AC\u03C3\u03B5\u03B9 \u03C4\u03BF\u03BD \u03C0\u03AF\u03BD\u03B1\u03BA\u03B1 \u03AC\u03BB\u03BB\u03C9\u03BD, \u03BA\u03B1\u03B9 \u03B8\u03B1 \u03BC\u03C0\u03BF\u03C1\u03BF\u03CD\u03BD \u03B1\u03BA\u03CC\u03BC\u03B1 \u03BD\u03B1 \u03C3\u03C5\u03BD\u03B5\u03B9\u03C3\u03C6\u03AD\u03C1\u03BF\u03C5\u03BD \u03C3\u03C4\u03B7\u03BD \u03B4\u03B9\u03BA\u03AE \u03C4\u03BF\u03C5\u03C2 \u03AD\u03BA\u03B4\u03BF\u03C3\u03B7.", shareTitle: "\u03A3\u03C5\u03BC\u03BC\u03B5\u03C4\u03AC\u03C3\u03C7\u03B5\u03C4\u03B5 \u03C3\u03B5 \u03BC\u03B9\u03B1 \u03B6\u03C9\u03BD\u03C4\u03B1\u03BD\u03AE \u03C3\u03C5\u03BD\u03B5\u03B4\u03C1\u03AF\u03B1 \u03C3\u03C5\u03BD\u03B5\u03C1\u03B3\u03B1\u03C3\u03AF\u03B1\u03C2 \u03B3\u03B9\u03B1 \u03C4\u03BF Excalidraw" };
