    u34 = { blog: "\u0628\u0644\u06C6\u06AF\u06D5\u06A9\u06D5\u0645\u0627\u0646 \u0628\u062E\u0648\u06CE\u0646\u06D5\u0648\u06D5", click: "\u06AF\u0631\u062A\u06D5", deepSelect: "\u062F\u06D5\u0633\u062A\u0646\u06CC\u0634\u0627\u0646\u06A9\u0631\u062F\u0646\u06CC \u0642\u0648\u06B5", deepBoxSelect: "\u0644\u06D5\u0646\u0627\u0648 \u0628\u06C6\u06A9\u0633\u06D5\u06A9\u06D5\u062F\u0627 \u0628\u06D5 \u0642\u0648\u0648\u06B5\u06CC \u0647\u06D5\u06B5\u0628\u0698\u06CE\u0631\u06D5\u060C \u0648 \u0695\u06CE\u06AF\u0631\u06CC \u0644\u06D5 \u0695\u0627\u06A9\u06CE\u0634\u0627\u0646 \u0628\u06A9\u06D5", curvedArrow: "\u062A\u06CC\u0631\u06CC \u0646\u0648\u0634\u062A\u0627\u0648\u06D5", curvedLine: "\u0647\u06CE\u06B5\u06CC \u0646\u0648\u0634\u062A\u0627\u0648\u06D5", documentation: "\u062F\u06C6\u06A9\u06CC\u0648\u0645\u06CE\u0646\u062A\u06D5\u06CC\u0634\u0646", doubleClick: "\u062F\u0648\u0648 \u06AF\u0631\u062A\u06D5", drag: "\u0631\u0627\u06A9\u06CE\u0634\u0627\u0646", editor: "\u062F\u06D5\u0633\u062A\u06A9\u0627\u0631\u06CC\u06A9\u06D5\u0631", editLineArrowPoints: "\u062F\u06D5\u0633\u062A\u06A9\u0627\u0631\u06CC \u062E\u0627\u06B5\u06D5\u06A9\u0627\u0646\u06CC \u0647\u06CE\u06B5/\u062A\u06CC\u0631 \u0628\u06A9\u06D5", editText: "\u062F\u06D5\u0633\u062A\u06A9\u0627\u0631\u06CC \u062F\u06D5\u0642 \u0628\u06A9\u06D5 / \u0644\u06D5\u06CC\u0628\u06B5\u06CE\u06A9 \u0632\u06CC\u0627\u062F \u0628\u06A9\u06D5", github: "\u06A9\u06CE\u0634\u06D5\u06CC\u06D5\u06A9\u062A \u062F\u06C6\u0632\u06CC\u06D5\u0648\u06D5\u061F \u067E\u06CE\u0634\u06A9\u06D5\u0634\u06A9\u0631\u062F\u0646", howto: "\u0634\u0648\u06CE\u0646 \u0695\u06CC\u0646\u0645\u0627\u06CC\u06CC\u06D5\u06A9\u0627\u0646\u0645\u0627\u0646 \u0628\u06A9\u06D5\u0648\u06D5", or: "\u06CC\u0627\u0646", preventBinding: "\u0695\u06CE\u06AF\u0631\u06CC\u0628\u06A9\u06D5 \u0644\u06D5 \u0646\u0648\u0634\u062A\u0627\u0646\u0627\u0648\u06D5\u06CC \u062A\u06CC\u0631", tools: "\u0626\u0627\u0645\u0631\u0627\u0632\u06D5\u06A9\u0627\u0646", shortcuts: "\u06A9\u0648\u0631\u062A\u06A9\u0631\u0627\u0648\u06D5\u06A9\u0627\u0646\u06CC \u062A\u06D5\u062E\u062A\u06D5\u06A9\u0644\u06CC\u0644", textFinish: "\u062A\u06D5\u0648\u0627\u0648\u06A9\u0631\u062F\u0646\u06CC \u062F\u06D5\u0633\u062A\u06A9\u0627\u0631\u06CC\u06A9\u0631\u062F\u0646 (\u062F\u06D5\u0633\u062A\u06A9\u0627\u0631\u06CC\u06A9\u06D5\u0631\u06CC \u062F\u06D5\u0642)", textNewLine: "\u0632\u06CC\u0627\u062F\u06A9\u0631\u062F\u0646\u06CC \u062F\u06CE\u0695\u06CC \u0646\u0648\u06CE (\u062F\u06D5\u0633\u062A\u06A9\u0627\u0631\u06CC\u06A9\u06D5\u0631\u06CC \u062F\u06D5\u0642)", title: "\u06CC\u0627\u0631\u0645\u0627\u062A\u06CC", view: "\u062F\u06CC\u0645\u06D5\u0646", zoomToFit: "\u0632\u0648\u0648\u0645 \u0628\u06A9\u06D5 \u0628\u06C6 \u0626\u06D5\u0648\u06D5\u06CC \u0644\u06D5\u06AF\u06D5\u06B5 \u0647\u06D5\u0645\u0648\u0648 \u062A\u0648\u062E\u0645\u06D5\u06A9\u0627\u0646\u062F\u0627 \u0628\u06AF\u0648\u0646\u062C\u06CE\u062A", zoomToSelection: "\u0632\u0648\u0648\u0645 \u0628\u06A9\u06D5 \u0628\u06C6 \u062F\u06D5\u0633\u062A\u0646\u06CC\u0634\u0627\u0646\u06A9\u0631\u0627\u0648\u06D5\u06A9\u0627\u0646", toggleElementLock: "\u0642\u0641\u06B5/\u06A9\u0631\u062F\u0646\u06D5\u0648\u06D5\u06CC \u062F\u06D5\u0633\u062A\u0646\u06CC\u0634\u0627\u0646\u06A9\u0631\u0627\u0648\u06D5\u06A9\u0627\u0646", movePageUpDown: "\u0644\u0627\u067E\u06D5\u0695\u06D5\u06A9\u06D5 \u0628\u062C\u0648\u06B5\u06CE\u0646\u06D5 \u0628\u06C6 \u0633\u06D5\u0631\u06D5\u0648\u06D5/\u062E\u0648\u0627\u0631\u06D5\u0648\u06D5", movePageLeftRight: "\u0644\u0627\u067E\u06D5\u0695\u06D5\u06A9\u06D5 \u0628\u062C\u0648\u06B5\u06CE\u0646\u06D5 \u0628\u06C6 \u0686\u06D5\u067E/\u0695\u0627\u0633\u062A" };
    h34 = { title: "\u062A\u0627\u0628\u0644\u06C6\u06A9\u06D5 \u062E\u0627\u0648\u06CE\u0646 \u0628\u06A9\u06D5\u0631\u06D5\u0648\u06D5" };
    y32 = { title: "\u067E\u06CE\u0634\u06A9\u06D5\u0634\u06A9\u0631\u062F\u0646\u06CC \u06A9\u062A\u06CE\u0628\u062E\u0627\u0646\u06D5", itemName: "\u0646\u0627\u0648\u06CC \u0628\u0695\u06AF\u06D5", authorName: "\u0646\u0627\u0648\u06CC \u0646\u0648\u0633\u06D5\u0631", githubUsername: "\u0646\u0627\u0648\u06CC \u0628\u06D5\u06A9\u0627\u0631\u0647\u06CE\u0646\u06D5\u0631\u06CC Github", twitterUsername: "\u0646\u0627\u0648\u06CC \u0628\u06D5\u06A9\u0627\u0631\u0647\u06CE\u0646\u06D5\u0631\u06CC Twitter", libraryName: "\u0646\u0627\u0648\u06CC \u06A9\u062A\u06CE\u0628\u062E\u0627\u0646\u06D5", libraryDesc: "\u0648\u06D5\u0633\u0641\u06CC \u06A9\u062A\u06CE\u0628\u062E\u0627\u0646\u06D5", website: "\u0645\u0627\u06B5\u067E\u06D5\u0695", placeholder: { authorName: "\u0646\u0627\u0648\u06D5\u06A9\u0627\u062A \u06CC\u0627\u062E\u0648\u062F \u0646\u0627\u0648\u06CC \u0628\u06D5\u06A9\u0627\u0631\u0647\u06CE\u0646\u06D5\u0631", libraryName: "\u0646\u0627\u0648\u06CC \u06A9\u062A\u06CE\u0628\u062E\u0627\u0646\u06D5\u06A9\u06D5\u062A", libraryDesc: "\u0648\u06D5\u0633\u0641\u06CC \u06A9\u062A\u06CE\u0628\u062E\u0627\u0646\u06D5\u06A9\u06D5\u062A \u0628\u06C6 \u06CC\u0627\u0631\u0645\u06D5\u062A\u06CC\u062F\u0627\u0646\u06CC \u062E\u06D5\u06B5\u06A9 \u0628\u06C6 \u062A\u06CE\u06AF\u06D5\u06CC\u0634\u062A\u0646 \u0644\u06D5 \u0628\u06D5\u06A9\u0627\u0631\u0647\u06CE\u0646\u0627\u0646\u06CC", githubHandle: "\u0646\u0627\u0648\u06CC GitHub (\u0626\u0627\u0631\u06D5\u0632\u0648\u0648\u0645\u06D5\u0646\u062F\u0627\u0646\u06D5)\u060C \u0628\u06C6\u06CC\u06D5 \u062F\u06D5\u062A\u0648\u0627\u0646\u06CC\u062A \u062F\u06D5\u0633\u062A\u06A9\u0627\u0631\u06CC \u06A9\u062A\u06CE\u0628\u062E\u0627\u0646\u06D5\u06A9\u06D5 \u0628\u06A9\u06D5\u06CC\u062A \u06A9\u0627\u062A\u06CE\u06A9 \u067E\u06CE\u0634\u06A9\u06D5\u0634 \u062F\u06D5\u06A9\u0631\u06CE\u062A \u0628\u06C6 \u067E\u06CE\u062F\u0627\u0686\u0648\u0648\u0646\u06D5\u0648\u06D5", twitterHandle: "\u0646\u0627\u0648\u06CC \u0628\u06D5\u06A9\u0627\u0631\u0647\u06CE\u0646\u06D5\u0631\u06CC \u062A\u0648\u06CC\u062A\u06D5\u0631 (\u0626\u0627\u0631\u06D5\u0632\u0648\u0648\u0645\u06D5\u0646\u062F\u0627\u0646\u06D5)\u060C \u0628\u06C6\u06CC\u06D5 \u0628\u0632\u0627\u0646\u06CC\u0646 \u0644\u06D5\u06A9\u0627\u062A\u06CC \u0628\u0627\u0646\u06AF\u06D5\u0634\u06D5\u06A9\u0631\u062F\u0646 \u0644\u06D5 \u0695\u06CE\u06AF\u06D5\u06CC \u062A\u0648\u06CC\u062A\u06D5\u0631\u06D5\u0648\u06D5 \u06A9\u0631\u06CC\u062F\u062A \u0628\u06C6 \u06A9\u06CE \u0628\u06A9\u06D5\u06CC\u0646", website: "\u0644\u06CC\u0646\u06A9\u06CC \u0645\u0627\u06B5\u067E\u06D5\u0695\u06CC \u062A\u0627\u06CC\u0628\u06D5\u062A\u06CC \u062E\u06C6\u062A \u06CC\u0627\u0646 \u0634\u0648\u06CE\u0646\u06CE\u06A9\u06CC \u062A\u0631 (\u0626\u0627\u0631\u06D5\u0632\u0648\u0645\u06D5\u0646\u062F\u0627\u0646\u06D5)" }, errors: { required: "\u062F\u0627\u0648\u0627\u06A9\u0631\u0627\u0648\u06D5", website: "URL\u06CE\u06A9\u06CC \u062F\u0631\u0648\u0633\u062A \u062A\u06CE\u0628\u0646\u0648\u0648\u0633\u06D5" }, noteDescription: "\u06A9\u062A\u06CE\u0628\u062E\u0627\u0646\u06D5\u06A9\u06D5\u062A \u0628\u0646\u06CE\u0631\u06D5 \u0628\u06C6 \u0626\u06D5\u0648\u06D5\u06CC \u0628\u062E\u0631\u06CE\u062A\u06D5 \u0646\u0627\u0648 <link>\u06A9\u06C6\u06AF\u0627\u06CC \u06A9\u062A\u06CE\u0628\u062E\u0627\u0646\u06D5\u06CC \u06AF\u0634\u062A\u06CC</link>\u0628\u06C6 \u0626\u06D5\u0648\u06D5\u06CC \u06A9\u06D5\u0633\u0627\u0646\u06CC \u062A\u0631 \u0644\u06D5 \u0648\u06CE\u0646\u06D5\u06A9\u06CE\u0634\u0627\u0646\u06D5\u06A9\u0627\u0646\u06CC\u0627\u0646\u062F\u0627 \u0628\u06D5\u06A9\u0627\u0631\u06CC \u0628\u0647\u06CE\u0646\u0646.", noteGuidelines: "\u06A9\u062A\u06CE\u0628\u062E\u0627\u0646\u06D5\u06A9\u06D5 \u067E\u06CE\u0648\u06CC\u0633\u062A\u06D5 \u0633\u06D5\u0631\u06D5\u062A\u0627 \u0628\u06D5 \u062F\u06D5\u0633\u062A \u067E\u06D5\u0633\u06D5\u0646\u062F \u0628\u06A9\u0631\u06CE\u062A. \u062A\u06A9\u0627\u06CC\u06D5 \u0628\u0641\u06D5\u0631\u0645\u0648 \u0628\u06D5 \u062E\u0648\u06CE\u0646\u062F\u0646\u06D5\u0648\u06D5\u06CC <link>\u0695\u06CE\u0646\u0645\u0627\u06CC\u06CC\u06D5\u06A9\u0627\u0646</link> \u067E\u06CE\u0634 \u067E\u06CE\u0634\u06A9\u06D5\u0634\u06A9\u0631\u062F\u0646. \u067E\u06CE\u0648\u06CC\u0633\u062A\u062A \u0628\u06D5 \u0626\u06D5\u0698\u0645\u06CE\u0631\u06CC GitHub \u062F\u06D5\u0628\u06CE\u062A \u0628\u06C6 \u067E\u06D5\u06CC\u0648\u06D5\u0646\u062F\u06CC\u06A9\u0631\u062F\u0646 \u0648 \u06AF\u06C6\u0695\u0627\u0646\u06A9\u0627\u0631\u06CC \u0626\u06D5\u06AF\u06D5\u0631 \u062F\u0627\u0648\u0627\u06CC \u0644\u06CE\u06A9\u0631\u0627\u060C \u0628\u06D5\u06B5\u0627\u0645 \u0628\u06D5 \u062A\u0648\u0646\u062F\u06CC \u067E\u06CE\u0648\u06CC\u0633\u062A \u0646\u06CC\u06CC\u06D5.", noteLicense: "\u0628\u06D5 \u067E\u06CE\u0634\u06A9\u06D5\u0634\u06A9\u0631\u062F\u0646\u060C \u062A\u06C6 \u0695\u06D5\u0632\u0627\u0645\u06D5\u0646\u062F\u06CC\u062A \u0644\u06D5\u0633\u06D5\u0631 \u0628\u06B5\u0627\u0648\u06A9\u0631\u062F\u0646\u06D5\u0648\u06D5\u06CC \u06A9\u062A\u06CE\u0628\u062E\u0627\u0646\u06D5\u06A9\u06D5 \u0628\u06D5\u067E\u06CE\u06CC <link>\u0645\u06C6\u06B5\u06D5\u062A\u06CC MIT\u060C </link>\u06A9\u06D5 \u0628\u06D5 \u06A9\u0648\u0631\u062A\u06CC \u0645\u0627\u0646\u0627\u06CC \u0626\u06D5\u0648\u06D5\u06CC\u06D5 \u06A9\u06D5 \u0647\u06D5\u0631\u06A9\u06D5\u0633\u06CE\u06A9 \u062F\u06D5\u062A\u0648\u0627\u0646\u06CE\u062A \u0628\u06D5 \u0628\u06CE \u0633\u0646\u0648\u0648\u0631 \u0628\u06D5\u06A9\u0627\u0631\u06CC \u0628\u0647\u06CE\u0646\u06CE\u062A", noteItems: "\u0647\u06D5\u0631 \u0634\u062A\u06CE\u06A9\u06CC \u06A9\u062A\u06CE\u0628\u062E\u0627\u0646\u06D5 \u062F\u06D5\u0628\u06CE\u062A \u0646\u0627\u0648\u06CC \u062A\u0627\u06CC\u0628\u06D5\u062A\u06CC \u062E\u06C6\u06CC \u0647\u06D5\u0628\u06CE\u062A \u0628\u06C6 \u0626\u06D5\u0648\u06D5\u06CC \u0628\u062A\u0648\u0627\u0646\u0631\u06CE\u062A \u0641\u0644\u062A\u06D5\u0631 \u0628\u06A9\u0631\u06CE\u062A. \u0626\u06D5\u0645 \u0628\u0627\u0628\u06D5\u062A\u0627\u0646\u06D5\u06CC \u06A9\u062A\u06CE\u0628\u062E\u0627\u0646\u0627\u0646\u06D5\u06CC \u062E\u0648\u0627\u0631\u06D5\u0648\u06D5 \u0644\u06D5\u062E\u06C6\u062F\u06D5\u06AF\u0631\u06CE\u062A:", atleastOneLibItem: "\u062A\u06A9\u0627\u06CC\u06D5 \u0628\u06D5\u0644\u0627\u06CC\u06D5\u0646\u06CC \u06A9\u06D5\u0645\u06D5\u0648\u06D5 \u06CC\u06D5\u06A9 \u0628\u0695\u06AF\u06D5\u06CC \u06A9\u062A\u06CE\u0628\u062E\u0627\u0646\u06D5 \u062F\u06CC\u0627\u0631\u06CC\u0628\u06A9\u06D5 \u0628\u06C6 \u062F\u06D5\u0633\u062A\u067E\u06CE\u06A9\u0631\u062F\u0646", republishWarning: "\u062A\u06CE\u0628\u06CC\u0646\u06CC: \u0647\u06D5\u0646\u062F\u06CE\u06A9 \u0644\u06D5 \u0626\u0627\u06CC\u062A\u0645\u06D5 \u062F\u06CC\u0627\u0631\u06CC\u06A9\u0631\u0627\u0648\u06D5\u06A9\u0627\u0646 \u0646\u06CC\u0634\u0627\u0646\u06A9\u0631\u0627\u0648\u0646 \u0648\u06D5\u06A9 \u0626\u06D5\u0648\u06D5\u06CC \u067E\u06CE\u0634\u062A\u0631 \u0628\u06B5\u0627\u0648\u06A9\u0631\u0627\u0648\u0646\u06D5\u062A\u06D5\u0648\u06D5/\u0646\u06CE\u0631\u062F\u0631\u0627\u0648\u0646. \u062A\u06D5\u0646\u0647\u0627 \u067E\u06CE\u0648\u06CC\u0633\u062A\u06D5 \u0634\u062A\u06D5\u06A9\u0627\u0646 \u062F\u0648\u0648\u0628\u0627\u0631\u06D5 \u067E\u06CE\u0634\u06A9\u06D5\u0634 \u0628\u06A9\u06D5\u06CC\u062A\u06D5\u0648\u06D5 \u0644\u06D5 \u06A9\u0627\u062A\u06CC \u0646\u0648\u06CE\u06A9\u0631\u062F\u0646\u06D5\u0648\u06D5\u06CC \u06A9\u062A\u06CE\u0628\u062E\u0627\u0646\u06D5\u06CC\u06D5\u06A9\u06CC \u0647\u06D5\u0628\u0648\u0648 \u06CC\u0627\u0646 \u067E\u06CE\u0634\u06A9\u06D5\u0634\u06A9\u0631\u062F\u0646." };
    S33 = { title: "\u06A9\u062A\u06CE\u0628\u062E\u0627\u0646\u06D5 \u067E\u06CE\u0634\u06A9\u06D5\u0634 \u06A9\u0631\u0627", content: "\u0633\u0648\u067E\u0627\u0633 {{authorName}}. \u06A9\u062A\u06CE\u0628\u062E\u0627\u0646\u06D5\u06A9\u06D5\u062A \u067E\u06CE\u0634\u06A9\u06D5\u0634 \u06A9\u0631\u0627\u0648\u06D5 \u0628\u06C6 \u067E\u06CE\u062F\u0627\u0686\u0648\u0648\u0646\u06D5\u0648\u06D5. \u062F\u06D5\u062A\u0648\u0627\u0646\u06CC\u062A \u0628\u06D5\u062F\u0648\u0627\u062F\u0627\u0686\u0648\u0648\u0646 \u0628\u06C6 \u062F\u06C6\u062E\u06D5\u06A9\u06D5 \u0628\u06A9\u06D5\u06CC\u062A<link>\u0644\u06CE\u0631\u06D5</link>" };
